// Generated by MCSuperMods: the tick trigger limiter of msm_runtime as a plain helper.
package msm_test;

import net.minecraft.server.level.ServerLevel;
import net.minecraft.world.entity.Entity;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/**
 * The shared cost ceiling of tick triggers: together they fire at most {@link #CAP} times per server tick; further
 * firings in that tick are skipped, and a skip is logged at most once a minute with the number skipped since the last
 * line. Server thread only.
 */
public final class TickLimiter {
    /** Firings per server tick. */
    public static final int CAP = 2000;
    /** Ticks between two log lines about skipped firings (one minute). */
    public static final int LOG_INTERVAL_TICKS = 1200;

    private static final Logger LOGGER = LoggerFactory.getLogger("msm_test");
    private static long tick = Long.MIN_VALUE;
    private static int fired;
    private static long skipped;
    private static long lastLog = Long.MIN_VALUE;

    private TickLimiter() {}

    /** Whether an interval trigger of {@code entity} is due this game tick (staggered by entity id). */
    public static boolean due(ServerLevel level, Entity entity, int interval) {
        return Math.floorMod(level.getGameTime() + entity.getId(), (long) interval) == 0;
    }

    /** Whether a tick trigger may fire now; counts the firing when it may. */
    public static synchronized boolean tryFire(ServerLevel level) {
        long now = level.getServer().getTickCount();
        if (now != tick) {
            tick = now;
            fired = 0;
        }
        if (fired < CAP) {
            fired++;
            return true;
        }
        skipped++;
        if (lastLog == Long.MIN_VALUE || now - lastLog >= LOG_INTERVAL_TICKS || now < lastLog) {
            LOGGER.warn("tick triggers: skipped {} firing(s) over the cap of {} per server tick", skipped, CAP);
            lastLog = now;
            skipped = 0;
        }
        return false;
    }
}
